config.message:
// BTN_A and BTN_B are the GPIO inputs wired into this node (bool: true = released,
// as a pressed button pulls its pin to GND). They send only when they change, so
// remember each button from its own changes; `from` says which one sent.
if (from == "BTN_A") pressedA = !BTN_A;
if (from == "BTN_B") pressedB = !BTN_B;
int out = (pressedA && pressedB) ? 1 : 0;
if (out != last) { // send only when the result changes
  last = out;
  send(out);
}
